 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 // Train the model at startup
 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
 var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

 var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

 // Map "Yes"/"No" → true/false using a serializable ValueMapping transform
 var lookupData = mlContext.Data.LoadFromEnumerable(new[]
 {
     new LabelMapping { Churned = "Yes", Label = true },
     new LabelMapping { Churned = "No", Label = false },
 });

 var pipeline = mlContext.Transforms.Conversion.MapValue(
         "Label",
         lookupData,
         lookupData.Schema[nameof(LabelMapping.Churned)],
         lookupData.Schema[nameof(LabelMapping.Label)],
         inputColumnName: nameof(CustomerData.Churned))
     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
     .Append(mlContext.Transforms.Concatenate("Features",
         nameof(CustomerData.Age),
         nameof(CustomerData.Income),
         "RegionEncoded",
         nameof(CustomerData.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label",
         featureColumnName: "Features"));

 var model = pipeline.Fit(split.TrainSet);

 // Evaluate on test set; handle small datasets where metrics may be undefined
 var predictions = model.Transform(split.TestSet);
 try
 {
     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
     Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
 }
 catch (ArgumentOutOfRangeException)
 {
     Console.WriteLine("Model trained — test set too small for full evaluation metrics. Add more data for reliable metrics.");
 }

